// Reads the schema (the MSD) and picks what to read: the first representation,
// its first route, and for each {param} in that route the model id segment
// behind it (models[].routes[].params). The index over that model is where a
// real value for the route comes from.
const msd = $input.first().json;
const representation = (msd.representations ?? [])[0];
if (!representation) throw new Error('The schema lists no representations.');
const route = (representation.$routes ?? [])[0];
if (!route) throw new Error(`Representation ${representation.$name} lists no routes.`);

const [model, entry] = Object.entries(msd.models ?? {})
	.map(([name, m]) => [name, (m.routes ?? []).find((r) => r.route === route && r.representation === representation.$name)])
	.find(([, r]) => r) ?? [];
if (!model) throw new Error(`The schema's models list no model behind ${route}.`);

const index = Object.entries(msd.indexes ?? {}).find(([, i]) => i.model === model)?.[0];
if (!index) throw new Error(`The schema lists no index over ${model}.`);

return [{
	json: {
		representation: representation.$name,
		route,
		model,
		idSegments: msd.models[model].idSegments,
		params: entry.params,
		index,
	},
}];

// Fills the route's {params} from the first match: a query item carries its
// record's raw id ($rawId for one id segment, $rawIds for several, in segment
// order), and params says which id segment each {param} takes.
const picked = $('Pick a representation from the schema').first().json;
const match = ($input.first().json.items ?? [])[0];
if (!match) throw new Error(`${picked.index} returned no documents to read.`);

const raw = match.$rawIds ?? [match.$rawId];
const value = (segment) => raw[picked.idSegments.indexOf(segment)];
const route = picked.route.replace(/\{([^}]+)\}/g, (_, param) =>
	encodeURIComponent(value(picked.params[param])),
);

return [{ json: { representation: picked.representation, route } }];

// One line per slot: its $state, so the two reads can be compared at a glance.
return $input.all().map((item) => {
	const metadata = item.json.$metadata ?? {};
	const slots = {};
	for (const [name, entry] of Object.entries(metadata)) {
		if (!name.startsWith('$')) slots[name] = entry?.$state;
	}
	return {
		json: {
			slots,
			checkpoint: typeof metadata.$resume === 'string' ? 'present (more to resume)' : 'none (nothing left open)',
			changedAt: metadata.$changedAt ?? null,
		},
	};
});

